export const defaultTheme={color:'#14655b',textColor:'#283b32',font:'Arial',layout:'classic',logo:'logo.png',signatureImage:'',showLogo:true};
export const neutralBusiness={address:'',phone:'',email:'',signatory:'',terms:'',paymentInfo:''};
export function validateTemplate(value){const name=String(value.name||'').trim();if(!name||name.length>80)throw Error('Enter a template name under 80 characters');const theme={...defaultTheme,...value.theme};if(!/^#[0-9a-f]{6}$/i.test(theme.color)||!/^#[0-9a-f]{6}$/i.test(theme.textColor))throw Error('Choose valid colors');if(!['Arial','Georgia','Verdana'].includes(theme.font)||!['classic','minimal','compact'].includes(theme.layout))throw Error('Choose a supported font and layout');for(const k of ['logo','signatureImage'])if(theme[k]&&theme[k]!=='logo.png'&&!/^data:image\/(png|jpeg|webp);base64,/.test(theme[k]))throw Error('Use PNG, JPG or WebP branding images');for(const k of ['logo','signatureImage'])if(String(theme[k]).length>700000)throw Error('Keep each branding image below 500 KB');const business=Object.fromEntries(Object.entries({...neutralBusiness,...value.business}).map(([k,v])=>[k,String(v??'')]));return {...value,name,theme,business};}
export function selectedBranding(store){const template=(store.data.settings.invoiceTemplates||[]).find(t=>t.id===store.data.settings.activeInvoiceTemplate&&!t.archived);return {theme:structuredClone(template?.theme||{...defaultTheme,logo:store.companyId==='default'?'logo.png':''}),business:{...(store.companyId==='default'?{}:neutralBusiness),...store.data.settings.invoiceBusiness,...template?.business},templateId:template?.id||''};}
export function saveTemplate(store,value){const template=validateTemplate(value),before=structuredClone(store.data);try{const rows=store.data.settings.invoiceTemplates||[],id=template.id||crypto.randomUUID();if(template.id&&!rows.some(t=>t.id===template.id))throw Error('Template not found');const saved={...template,id};store.data.settings.invoiceTemplates=[...rows.filter(t=>t.id!==id),saved];if(!store.data.settings.activeInvoiceTemplate)store.data.settings.activeInvoiceTemplate=id;store.save();return saved;}catch(err){store.data=before;throw err;}}
export function saveNumbering(store,{prefix='',padding=6,next}){if(!/^[A-Za-z0-9_-]{0,16}$/.test(prefix))throw Error('Use up to 16 letters, numbers, hyphens or underscores for the prefix');if(!Number.isInteger(Number(padding))||Number(padding)<3||Number(padding)>10)throw Error('Choose 3–10 number digits');const minimum=Math.max(store.companyId==='default'?3622:1,store.data.nextInvoice||0);if(!Number.isSafeInteger(Number(next))||Number(next)<minimum)throw Error('Next number must be at least '+minimum);const before=structuredClone(store.data);try{store.data.settings.invoiceNumbering={prefix,padding:Number(padding)};store.data.nextInvoice=Number(next);store.save();}catch(err){store.data=before;throw err;}}
